import{_ as n,o as a,c as e,ai as p}from"./chunks/framework.Ba-VnP44.js";const u=JSON.parse('{"title":"Project Context · 项目上下文","description":"","frontmatter":{},"headers":[],"relativePath":"ai/productivity/dev-spec/01-foundation/project-context.md","filePath":"ai/productivity/dev-spec/01-foundation/project-context.md"}'),l={name:"ai/productivity/dev-spec/01-foundation/project-context.md"};function i(r,s,t,c,d,b){return a(),e("div",null,[...s[0]||(s[0]=[p(`<h1 id="project-context-·-项目上下文" tabindex="-1">Project Context · 项目上下文 <a class="header-anchor" href="#project-context-·-项目上下文" aria-label="Permalink to “Project Context · 项目上下文”">​</a></h1><blockquote><p>第一层 · 能力底座。解决「AI 如何按需拿到准确的项目信息」——不是一次扫描整个仓库生成一堆没人看的文档，而是让 AI 在需要时能查到、查得准、有证据。</p></blockquote><h2 id="解决什么问题" tabindex="-1">解决什么问题 <a class="header-anchor" href="#解决什么问题" aria-label="Permalink to “解决什么问题”">​</a></h2><ul><li>每次开新对话都要重新解释项目背景。</li><li>AI 扫一遍仓库，上下文被无关代码占满，关键信息反而被稀释。</li><li>AI 靠命名和注释猜业务规则，把推测当成事实。</li><li>不知道哪些信息该长期保存、哪些该按任务临时提供。</li></ul><h2 id="核心内容" tabindex="-1">核心内容 <a class="header-anchor" href="#核心内容" aria-label="Permalink to “核心内容”">​</a></h2><h3 id="上下文分四层收敛" tabindex="-1">上下文分四层收敛 <a class="header-anchor" href="#上下文分四层收敛" aria-label="Permalink to “上下文分四层收敛”">​</a></h3><p>由外到内，每层有停止条件，能停就停，上一层没完成不进下一层：</p><table tabindex="0"><thead><tr><th>层次</th><th>产出</th><th>可以停的条件</th></tr></thead><tbody><tr><td>项目地图</td><td>模块清单 + 入口 + 构建方式</td><td>能说出「项目由哪几块组成」</td></tr><tr><td>模块地图</td><td>本次任务涉及的目录与子模块</td><td>能指出「改动落在哪个包」</td></tr><tr><td>调用链</td><td>入口 → 服务 → 数据完整路径</td><td>能画出「请求经过哪几层」</td></tr><tr><td>相关文件</td><td>待读待改文件清单（含不改但受影响的）</td><td>每个文件都能说出为何关心</td></tr></tbody></table><p><strong>明确跳过</strong>：<code>node_modules/</code>、<code>target/</code>、<code>dist/</code>、<code>.git/</code>、依赖目录、生成代码、大体积二进制。</p><p>追踪调用链时别只看同步调用，还要覆盖异步任务、消息消费、配置开关、动态 SQL。链条追到数据落点才算完：数据改在哪张表、事务边界在哪、异常最终怎么处理。</p><h3 id="长期保存-vs-按任务提供" tabindex="-1">长期保存 vs 按任务提供 <a class="header-anchor" href="#长期保存-vs-按任务提供" aria-label="Permalink to “长期保存 vs 按任务提供”">​</a></h3><table tabindex="0"><thead><tr><th>信息</th><th>放哪里</th><th>例子</th></tr></thead><tbody><tr><td>跨任务成立、能验证的事实</td><td>项目资料（README / docs）</td><td>技术栈、模块划分、构建命令、关键字段含义、历史决策</td></tr><tr><td>只有这次才有的信息</td><td>任务描述里给</td><td>本次目标、相关文件、验收标准</td></tr><tr><td>踩过的坑</td><td>known-issues / gotchas</td><td>某字段是可用量不是账面量</td></tr><tr><td>推测或未确认的信息</td><td>待确认清单</td><td>代码里查不到、需要人补充的</td></tr></tbody></table><p>一句话：<strong>能被证据验证且反复用到的，才沉淀；一次性的，留在任务里。</strong></p><h3 id="项目资料最小集" tabindex="-1">项目资料最小集 <a class="header-anchor" href="#项目资料最小集" aria-label="Permalink to “项目资料最小集”">​</a></h3><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>项目根目录/</span></span>
<span class="line"><span>├── README.md                 # 项目是什么、怎么跑</span></span>
<span class="line"><span>├── AGENTS.md                 # 项目级 AI 开发约定（按需）</span></span>
<span class="line"><span>├── docs/</span></span>
<span class="line"><span>│   ├── project-overview.md   # 模块、技术栈、关键设计</span></span>
<span class="line"><span>│   └── known-issues.md       # 已知问题与坑</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>已有文档能承担职责就复用，不要为了目录看起来完整而创建空文件。</p><h3 id="结论要标状态" tabindex="-1">结论要标状态 <a class="header-anchor" href="#结论要标状态" aria-label="Permalink to “结论要标状态”">​</a></h3><p>每条认知结论标注来源和状态：</p><ul><li><strong>已确认</strong>：有代码、配置或文档证据。</li><li><strong>待确认</strong>：现有资料查不到。</li><li><strong>人工补充</strong>：需要项目维护者提供。</li></ul><p>不要把「应该是」「一般是」写进正文。gotchas 由人写，不让 AI 代笔。</p><h2 id="可复制提示词" tabindex="-1">可复制提示词 <a class="header-anchor" href="#可复制提示词" aria-label="Permalink to “可复制提示词”">​</a></h2><details><summary><strong>项目地图（只读，不改文件）</strong></summary><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>你的任务只有一个：产出一份项目地图。不要修改任何文件，不要提改进建议。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>背景：我需要了解一个已有项目的整体结构，还没有开始任何开发。</span></span>
<span class="line"><span>目标：让我能回答「这个项目由哪几块组成、从哪里进入、怎么构建」。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>约束：</span></span>
<span class="line"><span>- 只读分析，不修改任何文件。</span></span>
<span class="line"><span>- 跳过 node_modules、target、dist、build、.git、vendor、依赖和生成目录。</span></span>
<span class="line"><span>- 优先读依赖与构建文件、README、启动入口、前端入口、配置和目录结构。</span></span>
<span class="line"><span>- 不逐个文件通读；结论带证据路径，推断单独放进「待确认」。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请输出：</span></span>
<span class="line"><span>1. 项目类型与技术栈</span></span>
<span class="line"><span>2. 模块清单（模块 → 职责一句话 → 入口文件路径）</span></span>
<span class="line"><span>3. 入口清单（启动类、前端入口、可执行脚本）</span></span>
<span class="line"><span>4. 目录结构概览（只列到有业务含义的那一层）</span></span>
<span class="line"><span>5. 构建、启动、测试命令（附来源文件）</span></span>
<span class="line"><span>6. 配置文件清单（路径 → 管什么）</span></span>
<span class="line"><span>7. 外部依赖（数据库、缓存、消息队列、第三方接口）</span></span>
<span class="line"><span>8. 本轮未覆盖范围</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br></div></div></details><details><summary><strong>调用链追踪（追到数据落点）</strong></summary><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>你的任务只有一个：追踪一条完整调用链，输出链路和数据流。不要修改任何文件。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>入口：&lt;接口描述，如 POST /api/mes/work-orders/{id}/report，或前端某提交按钮&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>约束：</span></span>
<span class="line"><span>- 从入口追到数据落点，中间不要停。</span></span>
<span class="line"><span>- 必须覆盖并说明：同步调用、异步任务、消息消费、配置开关、动态 SQL。</span></span>
<span class="line"><span>- 每步给出「文件路径:行号」和「方法名」。</span></span>
<span class="line"><span>- 找出事务边界和异常处理位置，指出这条链读写的表。</span></span>
<span class="line"><span>- 没找到的环节明确标「未找到」，不要跳过不提。</span></span>
<span class="line"><span>- 数据库结构以迁移脚本或实际库为准，不只凭实体类。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请输出：</span></span>
<span class="line"><span>1. 调用链总览（一行一步）</span></span>
<span class="line"><span>2. 逐层明细（层 | 文件:行号 | 方法 | 职责 | 数据变化）</span></span>
<span class="line"><span>3. 涉及的数据表（表名 | 读/写 | 关键字段）</span></span>
<span class="line"><span>4. 事务边界与异常处理</span></span>
<span class="line"><span>5. 隐藏路径（异步 / 消息 / 定时 / 动态 SQL）</span></span>
<span class="line"><span>6. 这条链上最容易出问题的几处及原因</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br></div></div></details><details><summary><strong>老项目接管（只读接入报告）</strong></summary><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>你现在需要接管一个已有项目。本轮只读分析，理解现状，建立后续开发所需的上下文。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>暂时不要修改任何业务代码、不要重构、不要安装新依赖。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>按顺序检查：</span></span>
<span class="line"><span>1. 技术栈及版本、前后端架构、模块划分、目录结构、主要依赖。</span></span>
<span class="line"><span>2. 如何启动、构建、测试，是否有数据库、Docker 等运行环境。</span></span>
<span class="line"><span>3. 核心业务模块、模块间调用、关键接口、重要数据实体、第三方集成。</span></span>
<span class="line"><span>4. 已有规则文件和项目代码规范。</span></span>
<span class="line"><span>5. 哪些模块不能随意改、哪些操作会影响生产数据、已知问题、代码里查不到的信息。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>输出项目接入报告，每项信息标注：已确认（有证据）/ 待确认 / 人工补充。</span></span>
<span class="line"><span>最后说明：是否具备开发条件，还缺什么信息，哪些建议写入规则，哪些等具体任务再分析。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div></details><h2 id="验收要点" tabindex="-1">验收要点 <a class="header-anchor" href="#验收要点" aria-label="Permalink to “验收要点”">​</a></h2><ul><li>[ ] 每条认知结论都有来源，推测都在「待确认」里。</li><li>[ ] 明确写出「未覆盖范围」。</li><li>[ ] 能回答五问：改哪几个文件、谁受影响、涉及哪张表哪个接口、现有实现为什么这么写、哪些地方不能碰。</li><li>[ ] 新项目命令已实际跑通；老项目确认没有架构级改动，diff 只有文档。</li><li>[ ] 没有创建无意义的空文档。</li></ul><p>五问里若有两条答不上来，回到对应层补，不要带着缺口改代码。</p>`,27)])])}const h=n(l,[["render",i]]);export{u as __pageData,h as default};
